    def _check_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path in py_files:
            content = authored[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer/span methods
                if isinstance(node, ast.Call):
                    func = node.func
                    if isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True
                    elif isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast_analysis',
                detail='Found OpenTelemetry import and tracer/span calls',
                duration_s=duration
            )

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry import found',
                duration_s=duration
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='OpenTelemetry imported but no tracer/span calls found',
                duration_s=duration
            )

        return GateResult(
            name='telemetry',
            status=FAILED,
            method='ast_analysis',
            detail='Telemetry check failed',
            duration_s=duration
        )
